"""Emit the generated help and skill modules for the self-hosted compiler."""

import hashlib
import re

from helpgen.shards import BUNDLE_PART_TEXT_BYTES, SHARD_SOURCE_BYTES, pack, split_text

GENERATED_HEADER = (
    "// GENERATED by scripts/generate_help.py from docs/spec/. Do not edit; "
    "run the script.\n"
)

# Upper bound, in bytes, for one emitted payload literal. Whole lines are packed
# into a chunk up to this size, so chunking never produces a literal longer than
# max(this cap, the longest source line). The verifier sizes its C string
# buffers by the longest literal in the module; chunks therefore never raise it.
VOW_LITERAL_CHUNK_BYTES = 2048


def _vow_escape(chunk: str) -> str:
    return chunk.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")


def _vow_payload_fn(name: str, text: str) -> str:
    """Emit `fn name() -> String` building `text` from chunked string literals.

    The payload is `text` (em dashes become `--`) plus a trailing newline, packed
    into whole-line chunks of at most VOW_LITERAL_CHUNK_BYTES (a longer line is a
    chunk of its own).
    """
    chunks: list[str] = []
    current = ""
    for line in text.replace("\u2014", "--").split("\n"):
        line += "\n"
        if current and len((current + line).encode()) > VOW_LITERAL_CHUNK_BYTES:
            chunks.append(current)
            current = ""
        current += line
    chunks.append(current)
    body = [f'    let r: String = String::from("{_vow_escape(chunks[0])}");']
    body += [
        f'    r.push_str(String::from("{_vow_escape(chunk)}"));' for chunk in chunks[1:]
    ]
    return "\n".join([f"fn {name}() -> String {{", *body, "    r", "}"])


def _module_file(
    module: str, blocks: list[tuple[str, str]], uses: list[str] | None = None
) -> str:
    """One whole generated module; each block sits between GENERATE markers."""
    camel = "".join(word.capitalize() for word in module.split("_"))
    lines = [GENERATED_HEADER + f"module {camel}"]
    lines += [f"use {name}" for name in uses or []]
    for marker, body in blocks:
        lines.append(f"\n// GENERATE:{marker}:START\n{body}\n// GENERATE:{marker}:END")
    return "\n".join(lines) + "\n"


def vow_help_files(json_str: str, human_str: str) -> dict[str, str]:
    blocks = [
        ("SKILL_JSON", _vow_payload_fn("skill_json", json_str)),
        ("SKILL_HUMAN", _vow_payload_fn("skill_human", human_str)),
    ]
    return {"compiler/help_text_gen.vow": _module_file("help_text_gen", blocks)}


def _vow_skill_support_content_fn_name(path: str) -> str:
    stem = re.sub(r"[^A-Za-z0-9]+", "_", path).strip("_").lower()
    if not stem:
        stem = "file"
    digest = hashlib.sha256(path.encode("utf-8")).hexdigest()[:8]
    return f"skill_support_content_{stem}_{digest}"


def _shard_files(
    prefix: str, items: list[tuple[str, str]]
) -> tuple[dict[str, str], list[str]]:
    """Pack payload functions into numbered modules; return (files, module names)."""
    files: dict[str, str] = {}
    modules: list[str] = []
    for number, shard in enumerate(pack(items, SHARD_SOURCE_BYTES), start=1):
        module = f"{prefix}_{number:02d}_gen"
        body = "\n\n".join(source for _, source in shard)
        files[f"compiler/{module}.vow"] = _module_file(module, [("SKILL_FULL", body)])
        modules.append(module)
    return files, modules


def vow_skill_files(
    entrypoint_md: str, bundle_md: str, support_files: dict[str, str]
) -> dict[str, str]:
    """The skill text modules: the entrypoint and dispatch, bundle parts, docs."""
    parts = split_text(bundle_md, BUNDLE_PART_TEXT_BYTES)
    part_names = [f"skill_bundle_part_{n:02d}" for n in range(1, len(parts) + 1)]
    bundle_items = [
        (name, _vow_payload_fn(name, text)) for name, text in zip(part_names, parts)
    ]
    doc_entries = [
        (path, _vow_skill_support_content_fn_name(path), body)
        for path, body in support_files.items()
    ]
    doc_items = [(fn, _vow_payload_fn(fn, body)) for _, fn, body in doc_entries]
    files, bundle_modules = _shard_files("skill_bundle", bundle_items)
    doc_files, doc_modules = _shard_files("skill_docs", doc_items)
    files.update(doc_files)

    bundle_fn = [
        "fn skill_bundle() -> String {",
        f"    let r: String = {part_names[0]}();",
        *[f"    r.push_str({name}());" for name in part_names[1:]],
        "    r",
        "}",
    ]
    lines = [
        _vow_payload_fn("skill_entrypoint", entrypoint_md),
        "",
        *bundle_fn,
        "",
        "fn skill_support_count() -> u64 {",
        f"    {len(doc_entries)}",
        "}",
        "",
        "fn skill_support_path(index: u64) -> String vow {",
        "    requires: index < skill_support_count()",
        "} {",
    ]
    for idx, (path, _, _) in enumerate(doc_entries):
        lines.append(
            f'    if index == {idx} {{ return String::from("{_vow_escape(path)}"); }}'
        )
    lines += [
        '    String::from("")',
        "}",
        "",
        "fn skill_support_content_index_guard(index: u64) vow {",
        "    requires: index < skill_support_count()",
        "} {",
        "    let _ok: i64 = 0;",
        "}",
        "",
        "fn skill_support_content(index: u64) -> String {",
        '    if index >= skill_support_count() { return String::from(""); }',
        "    skill_support_content_index_guard(index);",
    ]
    for idx, (_, fn, _) in enumerate(doc_entries):
        lines.append(f"    if index == {idx} {{ return {fn}(); }}")
    lines += ['    String::from("")', "}"]
    files["compiler/skill_text_gen.vow"] = _module_file(
        "skill_text_gen",
        [("SKILL_FULL", "\n".join(lines))],
        uses=bundle_modules + doc_modules,
    )
    return files
